import{b as a,O as i,g as n,j as t}from"./chunks/framework.DcaUmd3X.js";const g=JSON.parse('{"title":"查看状态与历史","description":"","frontmatter":{},"headers":[],"relativePath":"git/basics/status-log/index.md","filePath":"Git操作手册/2.基础操作/02.查看状态与历史.md","lastUpdated":1782199931000}'),e={name:"git/basics/status-log/index.md"};function l(p,s,h,d,o,k){return i(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="查看状态与历史" tabindex="-1">查看状态与历史 <a class="header-anchor" href="#查看状态与历史" aria-label="Permalink to &quot;查看状态与历史&quot;">​</a></h1><blockquote><p>git log / git status / git diff / git blame，看懂仓库里发生了什么</p></blockquote><h2 id="我刚提交的东西在哪看-——-git-log" tabindex="-1">我刚提交的东西在哪看？—— git log <a class="header-anchor" href="#我刚提交的东西在哪看-——-git-log" aria-label="Permalink to &quot;我刚提交的东西在哪看？—— git log&quot;">​</a></h2><p>上一章你提交了第一个版本。敲一下这个命令，就能看到它：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span></span></code></pre></div><p>输出大概长这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>commit a1b2c3d4e5f6... (HEAD -&gt; master)</span></span>
<span class="line"><span>Author: 张三 &lt;zhangsan@example.com&gt;</span></span>
<span class="line"><span>Date:   2024-06-13 15:30:00</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    第一次提交，搭建项目骨架</span></span></code></pre></div><p>从上到下依次是：commit id（唯一的身份证号）、作者、日期、提交信息。</p><blockquote><p>⚠️ 如果提交记录很多，<code>git log</code> 会进入分页模式——按 <code>q</code> 退出，按空格翻页，按上下箭头滚动。</p></blockquote><h3 id="让-log-更简洁" tabindex="-1">让 log 更简洁 <a class="header-anchor" href="#让-log-更简洁" aria-label="Permalink to &quot;让 log 更简洁&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 一行一条，最常用</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># a1b2c3d 第一次提交，搭建项目骨架</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># e4f5a6b 修复首页样式问题</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 只看最近 3 条</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # 显示每次具体改了什么代码</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stat</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # 显示每次改了哪些文件、增减几行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --graph</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 画出分支合并路线图</span></span></code></pre></div><h3 id="按条件筛选" tabindex="-1">按条件筛选 <a class="header-anchor" href="#按条件筛选" aria-label="Permalink to &quot;按条件筛选&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 看张三最近改了什么</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --author=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;张三&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 看最近一周的提交</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2024-06-01&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 搜提交信息里包含&quot;修复&quot;的</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --grep=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;修复&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span></span></code></pre></div><h2 id="现在仓库什么状态-——-git-status" tabindex="-1">现在仓库什么状态？—— git status <a class="header-anchor" href="#现在仓库什么状态-——-git-status" aria-label="Permalink to &quot;现在仓库什么状态？—— git status&quot;">​</a></h2><p><code>git status</code> 是日常使用频率最高的命令。每次准备干活前先敲一下，知道自己在哪、有什么改动：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>常见的四种输出，一眼就能看懂：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 干干净净</span></span>
<span class="line"><span>On branch master</span></span>
<span class="line"><span>nothing to commit, working tree clean</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 改了文件但还没 add</span></span>
<span class="line"><span>Changes not staged for commit:</span></span>
<span class="line"><span>  modified:   src/app.js</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 有新文件 Git 还没跟踪</span></span>
<span class="line"><span>Untracked files:</span></span>
<span class="line"><span>  images/logo.png</span></span>
<span class="line"><span></span></span>
<span class="line"><span># add 过了，等着被 commit</span></span>
<span class="line"><span>Changes to be committed:</span></span>
<span class="line"><span>  modified:   src/config.js</span></span></code></pre></div><p>想看精简版：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># M  src/app.js       ← M = 已修改，未暂存</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ?? images/logo.png  ← ?? = 未跟踪的新文件</span></span></code></pre></div><blockquote><p>💡 每次改完代码、敲 add 之前，先 <code>git status</code> 扫一眼——很多低级错误（比如调试用的 console.log 忘了删）就是这么发现的。</p></blockquote><h2 id="具体改了哪几行-——-git-diff" tabindex="-1">具体改了哪几行？—— git diff <a class="header-anchor" href="#具体改了哪几行-——-git-diff" aria-label="Permalink to &quot;具体改了哪几行？—— git diff&quot;">​</a></h2><p><code>git status</code> 告诉你有文件变了，<code>git diff</code> 告诉你具体变了哪些行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 工作区 vs 暂存区：还没 add 的修改</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 暂存区 vs 最新提交：add 了但还没 commit 的</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --staged</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 两个提交之间的差异</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> abc123</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> def456</span></span></code></pre></div><p>输出的 <code>-</code> 开头是删掉的行，<code>+</code> 开头是新增的行。和 git log 一样，内容多了会进分页模式，按 <code>q</code> 退出。</p><h2 id="这行代码谁写的-——-git-blame" tabindex="-1">这行代码谁写的？—— git blame <a class="header-anchor" href="#这行代码谁写的-——-git-blame" aria-label="Permalink to &quot;这行代码谁写的？—— git blame&quot;">​</a></h2><p>代码出了 bug，想知道这行是谁改的、在哪次提交引入的：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blame</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/app.js</span></span></code></pre></div><p>输出每一行前面会标注：commit id 缩写、作者、修改时间。IDE 里通常直接右键就能看到（VS Code 装 GitLens 插件体验更好），命令行也能快速定位。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>四个&quot;看&quot;的命令，各管一摊：</p><table tabindex="0"><thead><tr><th>命令</th><th>问的是什么</th><th>什么时候用</th></tr></thead><tbody><tr><td><code>git log</code></td><td>历史交了什么？</td><td>回顾进度、排查引入点</td></tr><tr><td><code>git status</code></td><td>当前什么状态？</td><td>干活前、add 前、push 前</td></tr><tr><td><code>git diff</code></td><td>具体改了什么？</td><td>add 之前检查代码</td></tr><tr><td><code>git blame</code></td><td>这行谁写的？</td><td>出 bug 追责</td></tr></tbody></table><blockquote><p>💡 记住 <code>q</code> 键——log 和 diff 输出太长卡住的时候，按 <code>q</code> 就能退出来。</p></blockquote><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>用 <code>git log --oneline</code> 看提交历史，试着加 <code>-p</code> 看看每次改了什么</li><li>修改一个文件 → 用 <code>git status</code> 看变化 → 用 <code>git diff</code> 看具体改了哪几行 → add → 再用 <code>git status</code> 看状态变化</li><li>用 <code>git blame</code> 看某个文件，找到某行是谁改的</li><li>连续做几次提交，然后用 <code>git log --graph --oneline</code> 看看效果</li></ol>`,35)])])}const r=a(e,[["render",l]]);export{g as __pageData,r as default};
